import { Hono } from 'hono'
import { cors } from 'hono/cors'
import { checkBearer } from '@argus/bearer-auth'
import { parseCheckInput, type HealthStatus, type ServiceCheck } from '@argus/watchtower-contract'
import { createRemoteJWKSet, jwtVerify, type JWTVerifyGetKey } from 'jose'

// Env is the global interface generated by `wrangler types` from this
// package's wrangler.jsonc bindings (worker-configuration.d.ts, gitignored),
// extended by src/worker/env.d.ts for the secrets below.

// Cloudflare Workers Routes don't strip the matched path prefix — a request
// to the API host's /watchtower/checks arrives at this Worker with the full
// /watchtower/checks path, not /checks. basePath() mounts every route below
// under that same prefix so the two stay in sync (same reason
// the retired email-mcp Worker used .basePath("/email")).
const app = new Hono<{ Bindings: Env }>().basePath('/watchtower')

app.use('*', cors())

app.get('/health', (c) => c.json({ ok: true }))

// Bearer token for the collector (a trusted homelab systemd service, not a
// browser session). Fails closed: with WATCHTOWER_COLLECTOR_TOKEN unset or
// empty every request is refused (argus#574).
app.post('/checks', async (c) => {
  if (!(await checkBearer(c.req.header('authorization'), c.env.WATCHTOWER_COLLECTOR_TOKEN))) {
    return c.json({ error: 'Unauthorized' }, 401)
  }

  let body: unknown
  try {
    body = await c.req.json()
  } catch {
    return c.json({ error: 'Invalid JSON body' }, 400)
  }

  const check = parseCheckInput(body)
  if (!check) {
    return c.json({ error: 'Malformed check body' }, 400)
  }

  // id/checked_at are server-generated, never trusted from the client —
  // matches today's DB-default invariant for checked_at (collector never
  // sets it) and gives every row a stable app-assigned id.
  const id = crypto.randomUUID()
  const checkedAt = new Date().toISOString()

  const detail = check.detail ? JSON.stringify(check.detail) : null

  // Latest-per-key upsert on every poll, history row only when the check
  // differs from the key's previous one. Both statements run in one D1 batch,
  // a single transaction, with the history insert first so its NOT EXISTS
  // guard still sees the previous latest row. `detail IS ?` matches NULL to
  // NULL. The upsert's WHERE keeps a newer latest row from being overwritten
  // by an older one.
  await c.env.DB.batch([
    c.env.DB.prepare(
      `INSERT INTO service_checks (id, service_key, host, status, detail, checked_at)
       SELECT ?, ?, ?, ?, ?, ?
       WHERE NOT EXISTS (
         SELECT 1 FROM service_checks_latest
         WHERE service_key = ? AND host = ? AND status = ? AND detail IS ?
       )`,
    ).bind(id, check.service_key, check.host, check.status, detail, checkedAt, check.service_key, check.host, check.status, detail),
    c.env.DB.prepare(
      `INSERT INTO service_checks_latest (service_key, host, status, detail, checked_at) VALUES (?, ?, ?, ?, ?)
       ON CONFLICT (service_key) DO UPDATE SET
         host = excluded.host, status = excluded.status, detail = excluded.detail, checked_at = excluded.checked_at
       WHERE excluded.checked_at >= service_checks_latest.checked_at`,
    ).bind(check.service_key, check.host, check.status, detail, checkedAt),
  ])

  return c.body(null, 204)
})

interface ServiceCheckRow {
  service_key: string
  host: string
  status: HealthStatus
  detail: string | null
  checked_at: string
}

// Supabase signs session tokens with an asymmetric key (ES256) and publishes
// the public half, so verifying needs only the project URL, never a secret.
// Workers hand over `env` per request rather than at module load, so the key
// set is built lazily and kept at module scope per project URL; jose caches
// the fetched keys inside it across requests. Mirrors apps/agent-engine's
// browserAccess.ts.
const jwksByProject = new Map<string, JWTVerifyGetKey>()

function projectKeys(supabaseUrl: string): { keys: JWTVerifyGetKey; issuer: string } {
  const base = supabaseUrl.replace(/\/+$/, '')
  const issuer = `${base}/auth/v1`
  let keys = jwksByProject.get(base)
  if (!keys) {
    keys = createRemoteJWKSet(new URL(`${issuer}/.well-known/jwks.json`))
    jwksByProject.set(base, keys)
  }
  return { keys, issuer }
}

// Latest rows older than this are expired from GET /checks (argus#869).
const STALE_AFTER_MS = 3 * 24 * 60 * 60 * 1000

// JWT-verifies the dashboard's existing Supabase session token against the
// project's JWKS — no new credential for the dashboard to manage. The
// algorithm allow-list keeps a token signed with the retired HS256 secret
// from ever verifying.
app.get('/checks', async (c) => {
  const header = c.req.header('authorization') ?? ''
  const token = header.startsWith('Bearer ') ? header.slice('Bearer '.length) : null
  if (!token) {
    return c.json({ error: 'Unauthorized' }, 401)
  }

  try {
    const { keys, issuer } = projectKeys(c.env.SUPABASE_URL)
    await jwtVerify(token, keys, { issuer, audience: 'authenticated', algorithms: ['ES256', 'RS256'] })
  } catch {
    return c.json({ error: 'Unauthorized' }, 401)
  }

  // One row per service_key, maintained by POST /checks (argus#676), so this
  // read is bounded by the number of keys rather than the history table.
  const { results } = await c.env.DB.prepare(
    `SELECT service_key, host, status, detail, checked_at
     FROM service_checks_latest
     ORDER BY service_key ASC`,
  ).all<ServiceCheckRow>()

  // argus#869: service_checks_latest has no TTL, so a row for a unit the
  // collector no longer checks would stay forever. Drop rows not checked in
  // STALE_AFTER_MS, but only while some row is newer than that: if every row
  // is old, the collector itself stopped, and the cards must stay up (the
  // dashboard marks them Stale) rather than vanish silently.
  const cutoff = new Date(Date.now() - STALE_AFTER_MS).toISOString()
  const collectorAlive = results.some((row) => row.checked_at >= cutoff)
  const visible = collectorAlive ? results.filter((row) => row.checked_at >= cutoff) : results

  const checks = visible.map((row): ServiceCheck => ({
    service_key: row.service_key,
    host: row.host,
    status: row.status,
    detail: row.detail ? (JSON.parse(row.detail) as Record<string, unknown>) : null,
    checked_at: row.checked_at,
  }))

  return c.json(checks)
})

// History retention. Nothing reads service_checks history: the dashboard
// shows only the latest row per key, served from service_checks_latest, which
// is never pruned. POST /checks writes a history row only when a key's status
// or detail changes (argus#844), so the table holds state transitions, not
// polls. Two days is enough for ad-hoc incident queries via
// `wrangler d1 execute`. Before argus#844 every poll wrote a row (~96k rows/day
// as of 2026-10, mostly 30s systemd polls) and 7 days of that filled 91% of the
// 500 MB D1 limit.
export const RETENTION_DAYS = 2

interface PruneOptions {
  batchSize?: number
  maxBatches?: number
}

// Deletes in bounded batches so no single statement runs long, and caps the
// batches per run to stay well inside the per-invocation D1 query limit. A
// backlog larger than one run's cap drains over successive cron runs.
// checked_at is compared lexically against a "Z" cutoff, which orders
// correctly against the Supabase-era "+00:00" rows too.
export async function pruneServiceChecks(
  db: D1Database,
  now: Date,
  { batchSize = 5000, maxBatches = 40 }: PruneOptions = {},
): Promise<number> {
  const cutoff = new Date(now.getTime() - RETENTION_DAYS * 24 * 60 * 60 * 1000).toISOString()
  const statement = db.prepare(
    `DELETE FROM service_checks WHERE rowid IN (
       SELECT rowid FROM service_checks WHERE checked_at < ? LIMIT ?
     )`,
  )

  let deleted = 0
  for (let batch = 0; batch < maxBatches; batch++) {
    const { meta } = await statement.bind(cutoff, batchSize).run()
    deleted += meta.changes
    if (meta.changes < batchSize) break
  }
  return deleted
}

export default {
  fetch: app.fetch,
  async scheduled(_controller, env, ctx) {
    ctx.waitUntil(
      pruneServiceChecks(env.DB, new Date()).then((deleted) => {
        console.log(`watchtower retention: pruned ${deleted} service_checks rows older than ${RETENTION_DAYS} days`)
      }),
    )
  },
} satisfies ExportedHandler<Env>
